import{_ as o,o as e,c as s,a2 as i}from"./chunks/framework.1C62pOns.js";const n="/pro-agent-hub-installer/capturas/pt/apps-detalhe.png",r="/pro-agent-hub-installer/capturas/pt/apps-designer.png",g=JSON.parse('{"title":"Apps","description":"","frontmatter":{},"headers":[],"relativePath":"pt/interface/apps.md","filePath":"pt/interface/apps.md","lastUpdated":1791171177000}'),t={name:"pt/interface/apps.md"};function p(d,a,l,c,u,m){return e(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="apps" tabindex="-1">Apps <a class="header-anchor" href="#apps" aria-label="Permalink to &quot;Apps&quot;">​</a></h1><p>Um <strong>App</strong> é uma tela web construída dentro da plataforma: formulário, painel, consulta. Ele tem endereço próprio, roda num processo separado e pode ser aberto por quem não é usuário do ProAgentHub.</p><p>É a resposta para &quot;e quando quem vai usar não deveria entrar no ProAgentHub?&quot;.</p><h2 id="aba-geral" tabindex="-1">Aba Geral <a class="header-anchor" href="#aba-geral" aria-label="Permalink to &quot;Aba Geral&quot;">​</a></h2><p><img src="'+n+'" alt="apps-detalhe"></p><p>Descrição, ícone (com o qual ele aparece no menu) e o <strong>slug</strong> — o pedaço final do endereço, <code>/a/&lt;slug&gt;</code>.</p><p>O <strong>modo de acesso</strong> decide quem entra:</p><ul><li><strong>Interno</strong> — exige usuário conectado, e respeita os grupos.</li><li><strong>Público</strong> — qualquer pessoa com o link abre, sem login.</li></ul><div class="danger custom-block"><p class="custom-block-title">Público é público mesmo</p><p>Num App público não existe usuário conectado: o código da página não tem quem identificar, e tudo o que ele expõe fica ao alcance de quem tiver o endereço. Não coloque atrás de um App público nada que você não publicaria numa página aberta.</p></div><h2 id="aba-global" tabindex="-1">Aba Global <a class="header-anchor" href="#aba-global" aria-label="Permalink to &quot;Aba Global&quot;">​</a></h2><p>CSS, JavaScript e um <strong>backend global</strong> compartilhados por todas as páginas. É onde ficam o tema, os utilitários e as funções que várias páginas chamam.</p><h2 id="aba-paginas" tabindex="-1">Aba Páginas <a class="header-anchor" href="#aba-paginas" aria-label="Permalink to &quot;Aba Páginas&quot;">​</a></h2><p><img src="'+r+`" alt="apps-designer"></p><p>Cada página declara como é feita, e isso é uma escolha por página:</p><ul><li><strong>Visual</strong> — montada arrastando componentes no designer. O HTML é gerado a partir da árvore.</li><li><strong>Código</strong> — HTML escrito à mão.</li></ul><div class="warning custom-block"><p class="custom-block-title">Não há sincronia de volta</p><p>Do visual sai HTML; do HTML <strong>não</strong> se remonta a árvore automaticamente. Existe uma importação de código→visual, mas é um passo único que você aciona de propósito, não um espelho. CSS e JS continuam editáveis à mão nos dois modos — é a saída de emergência para o que o designer não cobre.</p></div><h3 id="o-backend-da-pagina" tabindex="-1">O backend da página <a class="header-anchor" href="#o-backend-da-pagina" aria-label="Permalink to &quot;O backend da página&quot;">​</a></h3><p>Cada página tem uma aba de Python. <strong>Toda função de topo cujo nome não comece com <code>_</code> vira um endpoint</strong>, chamável do JavaScript da página com <code>proApp.call(&#39;nome&#39;, {…})</code>.</p><p>Não há rota nem decorador: a <strong>assinatura é o contrato</strong>. A mesma leitura do código que monta a lista de funções na tela valida os argumentos que chegam — por isso as duas não têm como divergir.</p><div class="tip custom-block"><p class="custom-block-title">Estado de módulo não sobrevive entre chamadas</p><p>O escopo é remontado a cada requisição, porque carrega o usuário conectado. Uma variável global não guarda nada de uma chamada para a outra. O que precisa persistir vai para <code>db</code>.</p></div><h3 id="os-dados-do-app" tabindex="-1">Os dados do App <a class="header-anchor" href="#os-dados-do-app" aria-label="Permalink to &quot;Os dados do App&quot;">​</a></h3><p>Cada App tem um banco MongoDB só dele, <code>app_&lt;id&gt;</code> — pelo número, não pelo slug, de modo que renomear o App nunca move os dados.</p><p>O código chega nele pelo <code>db</code> injetado ou pelas mesmas operações soltas no escopo (<code>save</code>, <code>find</code>, <code>delete</code>…). Não há conexão para abrir, nem como endereçar o banco de outro App. Ver <a href="/pro-agent-hub-installer/pt/funcoes/app_backend">Backend de página</a>.</p><p>O banco é <strong>apagado junto com o App</strong>.</p><h3 id="arquivos-enviados-pela-pagina" tabindex="-1">Arquivos enviados pela página <a class="header-anchor" href="#arquivos-enviados-pela-pagina" aria-label="Permalink to &quot;Arquivos enviados pela página&quot;">​</a></h3><p>Arraste o componente <strong>Arquivo</strong> para dentro de um formulário e dê um nome a ele — esse nome vira o parâmetro da função de backend, como em qualquer outro campo.</p><p>Ao clicar no botão que chama a função, a página envia o arquivo primeiro e passa ao Python o <strong>identificador</strong> dele. No backend:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> receber</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(anexo: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) -&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    dados </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> read_upload(anexo)          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># os bytes</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    info </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> upload_info(anexo)           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># nome, tipo, tamanho, quem enviou</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Recebi </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">info[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;filename&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{len</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dados)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bytes&quot;</span></span></code></pre></div><p>Marcando <strong>Vários arquivos</strong>, o parâmetro chega como uma lista de identificadores.</p><p>Os arquivos ficam no <strong>mesmo banco do App</strong>, ao lado dos dados dele — e valem as mesmas regras: não há como alcançar o arquivo de outro App, eles <strong>somem junto com o App</strong>, e <strong>não</strong> viajam na exportação (que leva a estrutura, não os dados de produção). O tamanho máximo é o da plataforma, em <code>PRO_AI_MAX_FILE_SIZE</code>.</p><p>Para listar ou apagar: <code>list_uploads()</code> e <code>delete_upload(id)</code>. Para oferecer o arquivo de volta na tela, <code>proApp.fileLink(id)</code> devolve o endereço de download.</p><div class="warning custom-block"><p class="custom-block-title">Em App público, o link de download só serve a quem enviou</p><p>Num App <strong>interno</strong> vale a mesma fronteira dos dados: quem pode abrir o App pode baixar os arquivos dele. Num App <strong>público</strong>, não — o link só entrega o arquivo a quem o enviou estando autenticado, e o que um visitante anônimo envia não sai por esse endereço de forma alguma. Sem isso, um formulário público que recebe documento pessoal entregaria o documento de um visitante a qualquer outro: o identificador do arquivo é sequencial o bastante para ser adivinhado.</p><p>Para mostrar esse conteúdo mesmo assim, faça-o pelo <strong>backend da página</strong> — <code>read_upload(id)</code> devolve os bytes, e ali é você quem decide quem vê o quê.</p></div><p>Em App público o envio também tem <strong>cota por visitante</strong> (por padrão, 10 arquivos ou 100 MB a cada 10 minutos). Quem passar disso recebe um aviso para tentar mais tarde: é a única porta da plataforma em que alguém sem cadastro escreve no banco, e sem cota um único visitante encheria o disco da instalação.</p><p>A contagem é feita <strong>na memória de cada réplica</strong> do serviço que publica os Apps, e a instalação padrão sobe duas: o teto que a instalação entrega é o dobro do número configurado. Se o limite precisar ser exato, suba uma réplica só ou aperte o valor.</p><h2 id="aba-previa" tabindex="-1">Aba Prévia <a class="header-anchor" href="#aba-previa" aria-label="Permalink to &quot;Aba Prévia&quot;">​</a></h2><p>Roda o App como ele vai ficar, inclusive com o conteúdo ainda não salvo. É o mesmo renderizador que serve o App publicado, então o que você vê é o que vai sair.</p><p>A prévia roda dentro de um <code>iframe</code> isolado, sem acesso à origem do hub — o JavaScript que você escreve não enxerga a sessão de quem está construindo.</p><h2 id="aba-versoes-e-publicacao" tabindex="-1">Aba Versões e publicação <a class="header-anchor" href="#aba-versoes-e-publicacao" aria-label="Permalink to &quot;Aba Versões e publicação&quot;">​</a></h2><p>Uma versão é o retrato do <strong>App inteiro</strong> — cabeçalho e todas as páginas. Publicar congela uma dessas versões, e é ela que responde em <code>/a/&lt;slug&gt;</code>.</p><p><strong>Editar o rascunho não muda o que está no ar.</strong> Só publicar de novo muda. É o que permite mexer com calma numa tela em uso.</p><h2 id="onde-os-apps-aparecem" tabindex="-1">Onde os Apps aparecem <a class="header-anchor" href="#onde-os-apps-aparecem" aria-label="Permalink to &quot;Onde os Apps aparecem&quot;">​</a></h2><p>Para quem usa, um App publicado é <strong>um item do menu lateral</strong>, e não uma linha numa tela de listagem. Quem constrói vê a lista em Apps; quem consome vê só o nome e o ícone que você deu.</p>`,42)])])}const b=o(t,[["render",p]]);export{g as __pageData,b as default};
